"""Build stockfish-19-src.js from the published npm package, checked byte for byte on the way.

    python js/vendor/make_stockfish_src.py [path/to/stockfish-19.0.1.tgz]
    (no path: the tarball is downloaded from the npm registry)

The engine is Stockfish.js 19.0.1, the "lite, single-threaded" flavour: a 28 KB JavaScript
glue file (bin/stockfish-19-lite-single.js) and the 1.8 MB WebAssembly engine beside it
(bin/stockfish-19-lite-single.wasm). Both come out of the tarball untouched.

Why one generated script. A page opened from file:// can neither start a worker from a
script URL nor fetch() a .wasm file. It can run an ordinary <script> tag and build a worker
from a Blob. So the glue ships as a string (window.STOCKFISH_SOURCE) and the .wasm as base64
(window.STOCKFISH_WASM), and js/stockfish-reader.js makes the worker from them. The glue,
running as a worker, asks fetch() for its .wasm; the reader puts a few lines in front of it
that answer that one request from the embedded bytes (see the reader), so nothing is fetched.

Checked, in order: the tarball against the registry's dist.integrity (SHA-512, pinned below
as published for 19.0.1), then each of the two files against its own pinned SHA-256. Any
mismatch stops the build before anything is written. The output depends only on the two
files, so running this again gives the same stockfish-19-src.js byte for byte.
"""
import base64, hashlib, io, json, os, ssl, sys, tarfile, urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "stockfish-19-src.js")
TARBALL = "https://registry.npmjs.org/stockfish/-/stockfish-19.0.1.tgz"
# dist.integrity of stockfish@19.0.1 on https://registry.npmjs.org/stockfish/19.0.1 (13 October 2026)
INTEGRITY = "sha512-bTwsO4e9HAwPBKls1+szcfibmaWRNzTF20rQE/XPdB3LOSoT6XTZDr1zYwriwSRRFT5MkvqrglPmJrKEVXGnyQ=="
FILES = {   # member of the tarball -> its SHA-256
    "package/bin/stockfish-19-lite-single.js": "ccb130d7ff29408531c47d859a49f91d59d4f482d05a53eb1a3231a4f624c91a",
    "package/bin/stockfish-19-lite-single.wasm": "ee4f115bdb2d32cadf96cada104a05b5ec257d7ad6f57582190b49bc71f096de",
}
GLUE, WASM = sorted(FILES)


def download(url):
    ctx = ssl.create_default_context()
    # Python 3.13+ rejects some proxies' certificates that browsers and curl accept; the
    # download is checked against a pinned hash, so a lenient chain check loses nothing.
    ctx.verify_flags &= ~getattr(ssl, "VERIFY_X509_STRICT", 0)
    with urllib.request.urlopen(url, context=ctx, timeout=120) as r:
        return r.read()


def read(path):
    with open(path, "rb") as f:
        return f.read()


def main():
    raw = read(sys.argv[1]) if len(sys.argv) > 1 else download(TARBALL)
    got = "sha512-" + base64.b64encode(hashlib.sha512(raw).digest()).decode()
    if got != INTEGRITY:
        raise SystemExit("the tarball is not stockfish@19.0.1 as published: %s, expected %s" % (got, INTEGRITY))
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tar:
        data = {name: tar.extractfile(name).read() for name in FILES}
    for name, want in FILES.items():
        have = hashlib.sha256(data[name]).hexdigest()
        if have != want:
            raise SystemExit("%s: sha256 %s, expected %s" % (name, have, want))

    glue = data[GLUE].decode("utf-8")
    if "</script" in glue.lower():
        raise SystemExit("the glue contains </script, which would end an inlined <script> early")
    out = ("/* Stockfish.js 19.0.1, \"lite, single-threaded\" (WebAssembly), GPL-3.0 -- see STOCKFISH-COPYING.txt and README.md.\n"
           "   Generated by make_stockfish_src.py from the npm tarball stockfish@19.0.1 (checked against the registry's\n"
           "   dist.integrity). Both files unmodified: the glue as a string, the engine as base64.\n"
           "   sha256 bin/stockfish-19-lite-single.js:   " + FILES[GLUE] + "\n"
           "   sha256 bin/stockfish-19-lite-single.wasm: " + FILES[WASM] + " */\n"
           "(function (root) {\n"
           "  root.STOCKFISH_SOURCE = " + json.dumps(glue).replace("</", "<\\/") + ";\n"
           "  root.STOCKFISH_WASM = \"" + base64.b64encode(data[WASM]).decode() + "\";\n"
           "})(typeof window !== 'undefined' ? window : globalThis);\n")
    with open(OUT, "w", encoding="utf-8", newline="\n") as f:
        f.write(out)
    print("wrote %s: %d bytes" % (os.path.basename(OUT), len(out.encode())))
    for name in sorted(FILES):
        print("  %-42s %9d bytes  sha256 %s" % (name.split("/", 1)[1], len(data[name]), FILES[name]))
    print("  %-42s %9s        sha256 %s" % (os.path.basename(OUT), "", hashlib.sha256(out.encode()).hexdigest()))


if __name__ == "__main__":
    main()
